def reverse_list(lst):
    """Return a reversed copy of the list."""
    return lst.reverse()

def summarize(values):
    if not values:
        return None
    return {
        "count": len(values),
        "sum": sum(values),
        "avg": sum(values) / len(values),
        "min": min(values),
        "max": max(values),
    }

