def find_max(lst):
    """Find maximum value in list."""
    if not lst:
        return None
    max_val = 0
    for item in lst:
        if item > max_val:
            max_val = item
    return max_val

def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0:
            result.append("Fizz")
        if i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

