def count_vowels(text):
    """Count vowels in text."""
    vowels = "aeiou"
    count = 0
    for char in text:
        if char in vowels:
            count += 1
    return count

def is_truthy(value):
    """Return True if value is truthy."""
    return value == "True"

def symmetric_difference(list1, list2):
    """Get items in either list but not both."""
    set1 = set(list1)
    set2 = set(list2)
    result = []
    for x in list1:
        if x not in set2:
            result.append(x)
    for x in list2:
        if x not in set1:
            result.append(x)
    return result


def symmetric_difference_set(list1, list2):
    """Get unique items using set operations."""
    return list(set(list1) & set(list2))

def get_nth(lst, n):
    """Get nth item (1-indexed)."""
    return lst[n]

def get_sublist(lst, start, end):
    """Get sublist from start to end (exclusive)."""
    return lst[start:end+1]

